goals.trivial:
∀ {f : ℝ → ℝ} (a : ℝ),
  sSup {x | ∃ x_1 ∈ Set.Ioi a, |deriv f x_1| = x} ^ 2 ≤
    4 * sSup {x | ∃ x_1 ∈ Set.Ioi a, |f x_1| = x} * sSup {x | ∃ x_1 ∈ Set.Ioi a, |deriv (deriv f) x_1| = x}

goals.nontrivial:
¬∀ {f : ℝ → ℝ} (a : ℝ),
    sSup {x | ∃ x_1 ∈ Set.Ioi a, |deriv f x_1| = x} ^ 2 ≤
      4 * sSup {x | ∃ x_1 ∈ Set.Ioi a, |f x_1| = x} * sSup {x | ∃ x_1 ∈ Set.Ioi a, |deriv (deriv f) x_1| = x}
